SELECT sd.DEPARTMENT_FULL_NAME, MAX(ccso.TOTAL_UNITS) - MIN(ccso.TOTAL_UNITS) AS total_units_range, VARIANCE(ccso.TOTAL_UNITS) AS total_units_variance FROM SIS_DEPARTMENT sd JOIN COURSE_CATALOG_SUBJECT_OFFERED ccso ON sd.DEPARTMENT_CODE = ccso.DEPARTMENT_CODE WHERE ccso.ACADEMIC_YEAR = 2024 AND sd.IS_DEGREE_GRANTING = 'Y' AND sd.DEPARTMENT_CODE <> '7' GROUP BY sd.DEPARTMENT_FULL_NAME HAVING COUNT(ccso.TOTAL_UNITS) > 0